import { test, expect } from '@playwright/test';

test.describe('Table Row Expansion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><table><tr><td>Item 1</td><td><button>Expand</button></td></tr><tr class="details" style="display:none"><td colspan="2">Nested details for Item 1</td></tr><tr><td>Item 2</td><td><button>Expand</button></td></tr><tr class="details" style="display:none"><td colspan="2">Nested details for Item 2</td></tr></table></body></html>');
  });

  test('should expand a row to reveal nested details', async ({ page }) => {
    const expandButtons = page.getByRole('button', { name: 'Expand' });
    const firstButton = expandButtons.first();

    await firstButton.click();

    const detailsRow = page.locator('tr.details').first();
    await expect(detailsRow).toBeVisible();
  });

  test('should display correct nested details when expanding different rows', async ({ page }) => {
    const expandButtons = page.getByRole('button', { name: 'Expand' });

    await expandButtons.nth(1).click();

    const detailsRows = page.locator('tr.details');
    const secondDetailsRow = detailsRows.nth(1);

    await expect(secondDetailsRow).toBeVisible();
    await expect(secondDetailsRow).toContainText('Nested details for Item 2');
  });

  test('should collapse row when clicking expand button again', async ({ page }) => {
    const expandButtons = page.getByRole('button', { name: 'Expand' });
    const firstButton = expandButtons.first();

    await firstButton.click();
    const detailsRow = page.locator('tr.details').first();
    await expect(detailsRow).toBeVisible();

    await firstButton.click();
    await expect(detailsRow).not.toBeVisible();
  });
});
